SELECT

FROM message_batches mb
WHERE mb.workspace_uuid = #{workspaceUUID}
AND mb.external_id = #{externalID}
AND mb.deleted_at IS NULL

SELECT

FROM message_batches mb
WHERE mb.uuid = #{batchUUID}

SELECT uuid, created_at
FROM message_batches
WHERE workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL

SELECT EXISTS(
    SELECT 1
    FROM message_batches
    WHERE workspace_uuid = #{workspaceUUID}
    AND external_id = #{externalID}
    AND deleted_at IS NULL
)

SELECT processing_status
FROM message_batches
WHERE workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL

SELECT

FROM message_batch_requests
WHERE message_batch_uuid = #{batchUUID}
AND request_index = #{requestIndex}
